CREATE DATABASE IF NOT EXISTS neon_blog DEFAULT CHARACTER SET utf8mb4;USE neon_blog;CREATE TABLE IF NOT EXISTS posts(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(255),content TEXT,author VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(120) UNIQUE,password VARCHAR(255),nickname VARCHAR(80) NOT NULL DEFAULT '林墨',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
